import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    customer_profile = inputs["customer_profile"].copy()
    profile_changes = inputs["profile_changes"].copy()

    # Ensure proper types
    customer_profile["customer_id"] = customer_profile["customer_id"].astype("int64")
    customer_profile["updated_seq"] = customer_profile["updated_seq"].astype("int64")
    profile_changes["customer_id"] = profile_changes["customer_id"].astype("int64")
    profile_changes["change_seq"] = profile_changes["change_seq"].astype("int64")

    # Convert string columns to object type for proper null handling
    for col in ["email", "phone", "tier"]:
        if col in customer_profile.columns:
            customer_profile[col] = customer_profile[col].astype("object")
        if col in profile_changes.columns:
            profile_changes[col] = profile_changes[col].astype("object")

    # Replace pd.NA and np.nan with None for consistent null handling
    for col in ["email", "phone", "tier"]:
        if col in customer_profile.columns:
            customer_profile[col] = customer_profile[col].where(pd.notna(customer_profile[col]), None)
        if col in profile_changes.columns:
            profile_changes[col] = profile_changes[col].where(pd.notna(profile_changes[col]), None)

    # Sort changes by customer_id and change_seq to process in order
    profile_changes = profile_changes.sort_values(["customer_id", "change_seq"]).reset_index(drop=True)

    # Initialize result as a copy of customer_profile
    result_rows = {}

    # Load existing profiles into result
    for _, row in customer_profile.iterrows():
        cid = row["customer_id"]
        result_rows[cid] = {
            "customer_id": cid,
            "email": row["email"],
            "phone": row["phone"],
            "tier": row["tier"],
            "updated_seq": row["updated_seq"]
        }

    # Process each change
    for _, change in profile_changes.iterrows():
        cid = change["customer_id"]
        change_seq = change["change_seq"]

        # Check if customer exists in result
        if cid in result_rows:
            existing = result_rows[cid]
            # Skip if change_seq <= updated_seq (already applied)
            if change_seq <= existing["updated_seq"]:
                continue

            # Apply change rules: NULL means no change, '<<NULL>>' means set to NULL
            old_email = existing["email"]
            old_phone = existing["phone"]
            old_tier = existing["tier"]

            new_email = old_email
            new_phone = old_phone
            new_tier = old_tier

            if change["email"] is not None:
                if change["email"] == "<<NULL>>":
                    new_email = None
                else:
                    # Store as LOWER(TRIM(email))
                    new_email = change["email"].strip().lower()

            if change["phone"] is not None:
                if change["phone"] == "<<NULL>>":
                    new_phone = None
                else:
                    new_phone = change["phone"]

            if change["tier"] is not None:
                if change["tier"] == "<<NULL>>":
                    new_tier = None
                else:
                    new_tier = change["tier"]

            # Check if row is identical (NULL-safe comparison)
            is_identical = (
                (old_email == new_email or (old_email is None and new_email is None)) and
                (old_phone == new_phone or (old_phone is None and new_phone is None)) and
                (old_tier == new_tier or (old_tier is None and new_tier is None))
            )

            if not is_identical:
                # Update the row
                existing["email"] = new_email
                existing["phone"] = new_phone
                existing["tier"] = new_tier
                existing["updated_seq"] = change_seq
        else:
            # Customer does not exist - create new row
            new_email = None
            new_phone = None
            new_tier = None

            if change["email"] is not None and change["email"] != "<<NULL>>":
                new_email = change["email"].strip().lower()

            if change["phone"] is not None and change["phone"] != "<<NULL>>":
                new_phone = change["phone"]

            if change["tier"] is not None and change["tier"] != "<<NULL>>":
                new_tier = change["tier"]

            result_rows[cid] = {
                "customer_id": cid,
                "email": new_email,
                "phone": new_phone,
                "tier": new_tier,
                "updated_seq": change_seq
            }

    # Convert result to DataFrame
    if result_rows:
        new_profile = pd.DataFrame(list(result_rows.values()))
    else:
        new_profile = pd.DataFrame(columns=["customer_id", "email", "phone", "tier", "updated_seq"])

    # Ensure proper column order and types
    new_profile = new_profile[["customer_id", "email", "phone", "tier", "updated_seq"]]
    new_profile["customer_id"] = new_profile["customer_id"].astype("int64")
    new_profile["updated_seq"] = new_profile["updated_seq"].astype("int64")

    return {"new_profile": new_profile}
